    vocab=[("PIB", "valor de los bienes y servicios finales producidos en un país en un período"), ("crecimiento económico", "aumento de lo que un país produce en un período"), ("desarrollo social", "mejora del bienestar en educación, salud, vivienda y empleo"), ("pobreza", "situación en que los recursos no alcanzan para las necesidades básicas"), ("desigualdad", "diferencia en la forma en que se reparten ingreso, riqueza u oportunidades"), ("matriz productiva", "conjunto de actividades que generan la riqueza de un país"), ("diversificación", "no depender de pocos productos o actividades")],
